        "dua_iftar_host" to DuaText("যেতিয়া আনৰ সৈতে দ্ৰুতভাৱে বিচ্ছেদ ঘটে", "উপবাস কৰা লোকসকলে আপোনাৰ সৈতে উপবাস ভংগ কৰক, ধাৰ্মিকসকলে আপোনাৰ খাদ্য খাওক, আৰু দূতে আপোনাৰ বাবে প্ৰাৰ্থনা কৰক।", "যেতিয়া কাৰোবাৰ ঘৰত উপবাস ভংগ কৰে।", "প্ৰতিনিধিৰ বাবে নবীৰ বাণী।"),
        "dua_seeing_first_fruit" to DuaText("প্ৰথম ফলটো দেখা", "হে আল্লাহ, আমাৰ ফলৰ বাবে আমাক আশীৰ্বাদ দিয়ক, আমাৰ চহৰত আমাক আশীৰ্বাদ দিয়ক, আৰু আমাৰ সা'আৰু আমাৰ খাদ (পৰিমাপ) ৰ বাবে আমাক আশীৰ্বাদ দিয়ক।", "ঋতুৰ প্ৰথম ফল দেখি।", "প্ৰদান আৰু নিজৰ চহৰত আশীৰ্বাদৰ বাবে এটা দুআ।"),
        "dua_good_news" to DuaText("আনন্দদায়ক বাতৰিৰ ওপৰত", "সকলো প্রশংসা আল্লাহৰ বাবে, যাৰ অনুগ্ৰহৰ দ্বাৰা ভাল বস্তু সম্পূৰ্ণ হয়।", "শুভ সংবাদ পোৱাৰ পিছত (আৰু কৃতজ্ঞতাৰ প্ৰাৰ্থনা কৰক)।", "নবী (ছাঃ)-এ তেওঁৰ ভাল লগা কিবা এটা দেখি এই কথা কৈছিল।"),
        "dua_looking_mirror" to DuaText("আইনাত চাই থকা", "হে আল্লাহ, তুমি মোৰ চেহেৰা যেনেকৈ ভাল কৰিছা, মোৰ চৰিত্ৰটোও ভাল কৰা।", "আইনাত চাই থকাৰ সময়ত।", "নবী ছলীহ আলীহ ৱাছলে এই দুআটো কৰিছিল (ই আইনাৰ উল্লেখ নোহোৱাকৈয়ে প্ৰতিষ্ঠিত)।"),
        "dua_rabbana_taqabbal" to DuaText("কৰ্মসমূহ গ্ৰহণ কৰা", "হে আমাৰ প্ৰভু, আমাৰ পৰা এই কথা গ্ৰহণ কৰক, নিশ্চয় তুমি সর্বশ্রোতা, সর্বজ্ঞাতা। আৰু আমাৰ তওবা গ্ৰহণ কৰক, নিশ্চয় তুমি তওবা কৰা, দয়াময়।", "কা'বা নিৰ্মাণৰ সময়ত ইব্ৰাহিম আৰু ইছমাইল (এ. এছ.)-এ সুধিছিল।", "প্ৰতিটো ভাল কামৰ পিছত গ্ৰহণ কৰাৰ বাবে এটা দুআ।"),
        "dua_muawwidhat" to DuaText("তিনিটা কুল (মু'ৱিধত)", "(ছুৰাহ আল-ইখলাস) কওকঃ তেওঁ হৈছে আল্লাহ, এজন। আল্লাহ, আত্মনিৰ্ভৰশীল। তেওঁৰ জন্ম নহয় আৰু তেওঁৰ সৈতে কোনো তুলনা নাই।\n\n(ছুৰাহ আল-ফালাক) কওকঃ মই প্ৰভুৰ ওচৰত আশ্ৰয় বিচাৰো, তেওঁ যি সৃষ্টি কৰিছে তাৰ দুষ্টতাৰ পৰা, অন্ধকাৰৰ দুষ্টতাৰ পৰা যেতিয়া ই স্থায়ী হয়, গাঁঠিৰ ওপৰত ফুৰাৰ দুষ্টতাৰ পৰা, আৰু ঈর্ষান্বিত হোৱাৰ দুষ্টতাৰ পৰা যেতিয়া তেওঁ ঈর্ষা কৰে।\n\n(ছুৰাহ আন-নাস) কওকঃ মই মানৱজাতিৰ প্ৰভু, মানৱজাতিৰ ৰজা, মানৱজাতিৰ ঈশ্বৰৰ ওচৰত আশ্ৰয় বিচাৰো, পিছ পৰি থকা ফিসফিস কৰা লোকৰ দুষ্টতাৰ পৰা, যি জিন আৰু মানৱজাতিৰ মাজত মানৱজাতিৰ হৃদয়ত ফিসফিস কৰে।", "তিনিটা ছুৰা প্ৰতিদিনে ৰাতিপুৱা আৰু সন্ধিয়া তিনিবাৰ, আৰু শুৱাৰ আগতে, হাতত ফুৰাই শৰীৰৰ ওপৰত মুছে।", "ৰাতিপুৱা আৰু সন্ধিয়া তিনিবাৰ এইসমূহ পাঠ কৰাটোৱেই সকলোৰে বিপৰীতে যথেষ্ট।"),
        "dua_sabr" to DuaText("ধৈর্য আৰু দৃঢ়তাৰ বাবে", "হে আমাৰ প্ৰভু, আমাৰ ওপৰত ধৈৰ্য্য প্ৰয়োগ কৰক, আমাৰ ভৰি দৃঢ় কৰক আৰু অবিশ্বাসী লোকসকলৰ বিৰুদ্ধে আমাক সহায় কৰক।", "কষ্ট আৰু সংঘাতৰ সময়ত।", "তালুতৰ সেনাৰ ডুৱা।"),
        "dua_rabbana_innana_amanna" to DuaText("ক্ষমা আৰু অগ্নিৰ পৰা সুৰক্ষা", "হে আমাৰ প্ৰভু, আমি বিশ্বাস কৰিছোঁ, গতিকে আমাৰ পাপসমূহ ক্ষমা কৰক আৰু আমাক অগ্নিৰ শাস্তিৰ পৰা ৰক্ষা কৰক।", "এটা কোৰানিক দুআ।", "ঈশ্বৰ-ভয় কৰাৰ গুণসমূহৰ ভিতৰত এটা দুআ উল্লেখ কৰা হৈছে।"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("আমাৰ ক্ষেত্ৰত নিৰ্দেশনা (আশাব আল-কাহফ)", "হে আমাৰ প্ৰভু, আপোনাৰ পৰা আমাক দয়া দিয়ক আৰু আমাৰ ক্ষেত্ৰত আমাৰ বাবে সঠিক নিৰ্দেশনা প্ৰস্তুত কৰক।", "গুহাৰ লোকসকলৰ ডুৱা।", "সিদ্ধান্ত আৰু কঠিন পৰিস্থিতিত নিৰ্দেশনা।"),
        "dua_musa_faqir" to DuaText("ব্যৱস্থাৰ বাবে মুসাৰ দুআ (এ. এছ.)", "হে মোৰ প্ৰভু, তুমি মোক যি ভাল বস্তু প্ৰেৰণ কৰা, মোৰ সেইটোৰ সঁচাকৈয়ে প্ৰয়োজন।", "যোগান আৰু ভাল বিচাৰি থকা-মাদিয়নত মুসা (এ. এছ) ৰ দুআ।", "এই দুআৰ পিছত, আল্লাহে মূচাক (আৰু আছা) এটা ঘৰ, কাম আৰু পত্নী প্ৰদান কৰিছিল।"),
        "dua_ayyub" to DuaText("অসুস্থতাত থকা আয়ুবৰ দুৱা (এ. এছ.)", "(হে মোৰ প্ৰভু) ক্ষতি মোৰ ওপৰত পৰিছে, আৰু তুমি দৰ্শকসকলৰ ভিতৰত অতি দয়ালু।", "ৰোগ আৰু কষ্টত।", "আল্লাহে আইয়ুব (আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আৰু আ"),
        "dua_husn_khatimah" to DuaText("মুছলমান হিচাপে মৃত্যু (ইউছুফ এ. এছ.)", "হে আকাশমণ্ডলী আৰু পৃথিৱীৰ সৃষ্টিকৰ্তা, তুমি এই পৃথিৱী আৰু পৰৱৰ্তী সময়ত মোৰ ৰক্ষক। মোক মুছলমান হিচাপে মৰাই দিয়া আৰু সৎকাৰীসকলৰ সৈতে মোৰ লগত যোগ দিয়া।", "এটা ভাল সমাপ্তিৰ বাবে এটা ডুৱা।", "নবী ইউছুফ (আৰু. আৰ.)-ৰ দুআ।"),
        "dua_shaitan_hamazat" to DuaText("শয়তানৰ হুইচাৰ্ছৰ পৰা আশ্ৰয়", "হে মোৰ প্ৰভু, মই শয়তানৰ ফিসফিস কৰাৰ পৰা তোমাৰ আশ্ৰয় বিচাৰোঁ, আৰু হে মোৰ প্ৰভু, মই তোমাৰ আশ্ৰয় বিচাৰোঁ, নহ'লে সিহঁতে মোৰ ওচৰলৈ আহিব।", "শয়তানৰ ফিসফিসৰ পৰা আশ্ৰয়।", "আশ্ৰয় বিচৰাৰ এক কোৰানিক দুআ।"),
        "dua_bad_character" to DuaText("বেয়া চৰিত্ৰৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ ওচৰত বেয়া চৰিত্ৰ, বেয়া কাম আৰু বেয়া ইচ্ছাৰ পৰা আশ্ৰয় বিচাৰো।", "বেয়া চৰিত্ৰ, কৰ্ম আৰু ইচ্ছাৰ পৰা শৰণাধিকাৰ।", "নবী (ছাঃ)-ৰ পৰা এটা আশ্ৰয়ৰ দুৱা।"),
        "dua_zawal_nimah" to DuaText("আশীৰ্বাদ হেৰুওৱাৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ আশীৰ্বাদ হেৰুওৱাৰ পৰা, তুমি দিয়া কল্যাণৰ পৰিৱৰ্তনৰ পৰা, তোমাৰ আকস্মিক শাস্তিৰ পৰা আৰু তোমাৰ সকলো অসন্তুষ্টিৰ পৰা তোমাৰ আশ্ৰয় বিচাৰোঁ।", "আশীৰ্বাদ হেৰুওৱা আৰু আকস্মিক দুৰ্যোগৰ পৰা শৰণাৰ্থী।", "নবী (ছাঃ)-ৰ এটা দুআ।"),
        "dua_useless_knowledge" to DuaText("অ-উপকাৰী জ্ঞানৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ ওচৰত লাভ নোহোৱা জ্ঞানৰ পৰা, ভয় নকৰা হৃদয়ৰ পৰা, কেতিয়াও সন্তুষ্ট নোহোৱা আত্মাৰ পৰা আৰু উত্তৰ নোপোৱা দুআৰ পৰা আশ্ৰয় বিচাৰো।", "অকেজো জ্ঞান আৰু আল্লাহৰ ভয় নোহোৱা হৃদয়ৰ পৰা আশ্ৰয় লওক।", "নবী (ছাঃ)-ৰ পৰা এটা আশ্ৰয়ৰ দুৱা।"),
        "dua_beneficial_knowledge" to DuaText("উপকাৰী জ্ঞান আৰু হালাল ৰিজক", "হে আল্লাহ, মই তোমাৰ ওচৰত উপকাৰী জ্ঞান, বিশুদ্ধ খাদ্য আৰু গ্ৰহণযোগ্য কাৰ্য্যৰ বাবে অনুৰোধ কৰোঁ।", "ফজ্ৰ নামাজৰ পিছত।", "ফজরৰ ছালামৰ পিছত নবী ছলীহ আলীহ ৱাছলে এই কথা কৈছিল।"),
        "dua_leprosy_diseases" to DuaText("গুৰুতৰ ৰোগৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই আপোনাৰ ওচৰত ভিটিলিগ, উন্মাদতা, কুষ্ঠ ৰোগ আৰু সকলো দুষ্ট ৰোগৰ পৰা আশ্ৰয় বিচাৰো।", "গুৰুতৰ ৰোগৰ পৰা সুৰক্ষা।", "স্বাস্থ্য ৰক্ষাৰ বাবে এটা সুন্নাহ দুআ।"),
        "dua_fear_people" to DuaText("শত্ৰু বা নিৰ্যাতনৰ ভয়", "হে আল্লাহ, আমি তোমাক তেওঁলোকৰ সন্মুখত ৰাখিছোঁ আৰু তেওঁলোকৰ দুষ্টতাৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰি আছো।", "যেতিয়া কোনো মানুহ বা ব্যক্তিৰ ক্ষতিৰ ভয় কৰে।", "নবী (ছাঃ)-এ যেতিয়া এটা লোকক ভয় কৰিছিল তেতিয়া তেওঁ এই কথা কৈছিল।"),
        "dua_shirk_protection" to DuaText("লুকাই থকা শিৰ্কৰ পৰা সুৰক্ষা", "হে আল্লাহ, মই জানি বুজি তোমাৰ লগত যিকোনো বস্তুৰ সংগ দিয়াৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰো, আৰু মই অজান্তে কৰা কামৰ বাবে তোমাৰ পৰা ক্ষমা বিচাৰো।", "প্ৰদৰ্শন আৰু লুকাই থকা শিৰ্কৰ পৰা সুৰক্ষিত থাকিবলৈ।", "পিঁপড়িবোৰে বিচৰাৰ তুলনাত লুকাই ৰখা শিৰ্ক অধিক লুকুৱাই ৰখা হয়।"),
        "dua_rain" to DuaText("যেতিয়া বৰষুণ হয়", "হে আল্লাহ, এটা উপকাৰী বৰষুণ (পঠিওৱা)।", "যেতিয়া বৰষুণ হয়।", "বৰষুণ হৈছে এক সময় যেতিয়া দুৱা গ্ৰহণ কৰা হয়।"),
        "dua_after_rain" to DuaText("বৰষুণৰ পিছত", "আল্লাহৰ অনুগ্ৰহ আৰু তেওঁৰ দয়াৰ দ্বাৰা আমাক বৰষুণ দিয়া হৈছে।", "বৰষুণৰ পিছত।", "যিজনে এইটো কয় তেওঁ আল্লাহত বিশ্বাস কৰে।"),
        "dua_istisqa" to DuaText("বৰষুণৰ বাবে কোৱা (ইস্তিস্কা)", "হে আল্লাহ, আমাক তিনিবাৰ বৰষুণ দিয়ক।", "যেতিয়া বৰষুণ নহয়।", "নৱদূত ছলীহ আলীহ ৱাছলে শুক্ৰবাৰে দিয়া উপদেশত এই দুআ কৰিছিল আৰু বৰষুণ হৈছিল।"),
        "dua_heavy_rain" to DuaText("অত্যাধিক বৰষুণ", "হে আল্লাহ, (ইয়াক পৰিবলৈ দিয়ক) আমাৰ চাৰিওফালে, আমাৰ ওপৰত নহয়।", "যেতিয়া অত্যাধিক বৰষুণ হয়।", "মেঘবোৰ নবী (ছাঃ)-ৰ দুআৰ মাজেৰে আঁতৰি গৈছিল।"),
        "dua_wind" to DuaText("যেতিয়া বতাহ ওলাই", "হে আল্লাহ, মই তোমাৰ ওচৰত ইয়াৰ ভাল, ইয়াৰ ভিতৰৰ ভাল আৰু যিখিনি লগত পঠিওৱা হৈছিল তাৰ ভাল বিচাৰো, আৰু মই তোমাৰ ওচৰত ইয়াৰ বেয়া, ইয়াৰ ভিতৰৰ বেয়া আৰু যিখিনি লগত পঠিওৱা হৈছিল তাৰ বেয়াৰ পৰা আশ্ৰয় বিচাৰো।", "যেতিয়া তীব্ৰ বতাহ বা ধুমুহা হয়।", "প্ৰবক্তা ছলীহ আলীহ ৱাছলে ধুমুহাৰ সময়ত এই দুআ কৰিছিল।"),
        "dua_thunder" to DuaText("বজ্রধ্বনি শুনা", "যিজনক বজ্রধ্বনিৰ দ্বাৰা তেওঁৰ প্ৰশংসাৰে গৌৰৱান্বিত কৰে, আৰু তেওঁৰ ভয়ত দূতেসকলৰ গৌৰৱ হওক।", "বজ্ৰপাত শুনি-আব্দুল্লাহ ইবন আজ-জুবায়ৰ (আৰ. এ.) ৰ প্ৰথা।", "ছুৰাহ আৰ-ৰাদ (13:13) ৰ পৰা লোৱা হৈছে।"),
    )
}
